function appendQuestionEntry(run, questions, timestamp) {
    run.conversation.entries.push({
        ...createEventEntry(
            `${run.id}-question-${run.conversation.entries.length}`,
            'agentQuestion',
            '',
            timestamp,
            nextRunSequence(run),
